CREATE TABLE IF NOT EXISTS users(email TEXT PRIMARY KEY, token_hash TEXT UNIQUE NOT NULL, credits REAL NOT NULL DEFAULT 0, tokens INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, created TEXT, last TEXT, google_sub TEXT);
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, at TEXT, usd REAL, credits REAL, ref TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS usage(id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, at TEXT, input INTEGER, output INTEGER, credits REAL);
CREATE INDEX IF NOT EXISTS usage_email ON usage(email);
